input.command:
cat > /work/styles.css <<'EOF'
/* University course registration — shared styles.
   All color pairs were checked for WCAG 2.2 AA contrast (text 4.5:1, UI 3:1). */

:root {
  --ink: #1f2937;
  --ink-strong: #1e1b4b;
  --muted: #4b5563;
  --page: #f5f3ff;
  --surface: #ffffff;
  --primary: #4338ca;
  --primary-dark: #3730a3;
  --accent: #86198f;
  --danger: #b91c1c;
  --border: #6b7280;
  --focus: #1e1b4b;
  --focus-on-dark: #fde047;
  --radius: 0.75rem;
  --header-gradient: linear-gradient(110deg, #3730a3 0%, #5b21b6 50%, #86198f 100%);
}

*,
*::before,
*::after { box-sizing: border-box; }

html {
  scroll-padding-top: 6rem;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink);
  background: var(--page);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

img, svg { max-width: 100%; }

h1, h2, h3 { color: var(--ink-strong); line-height: 1.25; margin: 0 0 0.75rem; }
h1 { font-size: 2rem; }
h2 { font-size: 1.5rem; }
h3 { font-size: 1.2rem; }
p { margin: 0 0 1rem; }

a { color: var(--primary); text-decoration: underline; text-underline-offset: 0.15em; }
a:hover { color: var(--accent); text-decoration-thickness: 0.15em; }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
[tabindex="-1"]:focus { outline: none; }
[tabindex="-1"]:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: 1rem;
  top: -10rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  background: var(--surface);
  color: var(--ink-strong);
  font-weight: 700;
  border-radius: 0 0 0.5rem 0.5rem;
}
.skip-link:focus { top: 0; }

/* ---------- Header and navigation ---------- */
.site-header {
  background: var(--header-gradient);
  color: #fff;
  z-index: 50;
}
@media (min-width: 48em) and (min-height: 32em) {
  .site-header { position: sticky; top: 0; }
}
.site-header :focus-visible,
.hero :focus-visible,
.site-footer :focus-visible { outline-color: var(--focus-on-dark); }

.header-inner {
  max-width: 72rem;
  margin: 0 auto;
  padding: 0.5rem 1rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 1rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: #fff;
  font-weight: 800;
  font-size: 1.15rem;
  text-decoration: none;
  padding: 0.25rem 0;
  min-height: 2.75rem;
}
.brand:hover { color: #fff; text-decoration: underline; }
.brand svg { width: 2rem; height: 2rem; flex: none; }

.menu-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.9rem;
  font: inherit;
  font-weight: 700;
  color: #fff;
  background: transparent;
  border: 2px solid #fff;
  border-radius: 0.5rem;
  cursor: pointer;
}
.menu-toggle svg { width: 1.25rem; height: 1.25rem; }

.nav-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: none;
  width: 100%;
  flex-direction: column;
  gap: 0.25rem;
  padding-bottom: 0.5rem;
}
.nav-list.is-open { display: flex; }

.nav-list a {
  display: block;
  padding: 0.6rem 0.9rem;
  min-height: 2.75rem;
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  border-radius: 0.5rem;
  border-bottom: 3px solid transparent;
}
.nav-list a:hover { background: rgba(30, 27, 75, 0.45); color: #fff; text-decoration: underline; }
.nav-list a[aria-current="page"] {
  background: #1e1b4b;
  border-bottom-color: var(--focus-on-dark);
  text-decoration: underline;
  text-decoration-thickness: 0.15em;
}

.site-nav { width: 100%; }

@media (min-width: 48em) {
  .menu-toggle { display: none; }
  .site-nav { width: auto; }
  .nav-list,
  .nav-list.is-open {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    width: auto;
    padding-bottom: 0;
  }
}

/* ---------- Layout ---------- */
main {
  flex: 1 0 auto;
  width: 100%;
  max-width: 72rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 3rem;
}
main:focus { outline: none; }

.page-intro {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 1.25rem 1.5rem;
  margin-bottom: 1.5rem;
  border-left: 0.5rem solid var(--accent);
  box-shadow: 0 1px 3px rgba(30, 27, 75, 0.15);
}
.page-intro p:last-child { margin-bottom: 0; }

.panel {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 1.25rem 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: 0 1px 3px rgba(30, 27, 75, 0.15);
}
.panel > :last-child { margin-bottom: 0; }

/* ---------- Footer ---------- */
.site-footer {
  background: var(--ink-strong);
  color: #fff;
  flex: none;
}
.footer-inner {
  max-width: 72rem;
  margin: 0 auto;
  padding: 1.25rem 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem 2rem;
}
.site-footer p { margin: 0; }
.site-footer a { color: #fde047; }
.site-footer a:hover { color: #fff; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.55rem 1.2rem;
  font: inherit;
  font-weight: 700;
  line-height: 1.3;
  text-align: center;
  text-decoration: none;
  border: 2px solid var(--primary);
  border-radius: 0.5rem;
  cursor: pointer;
  background: var(--primary);
  color: #fff;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.btn:hover { background: var(--primary-dark); border-color: var(--primary-dark); color: #fff; text-decoration: underline; }
.btn-secondary { background: var(--surface); color: var(--primary); }
.btn-secondary:hover { background: #e0e7ff; color: var(--ink-strong); }
.btn-danger { background: var(--danger); border-color: var(--danger); }
.btn-danger:hover { background: #7f1d1d; border-color: #7f1d1d; }
.btn-small { min-height: 2.25rem; padding: 0.3rem 0.8rem; font-size: 0.95rem; }
.btn-light { background: #fff; color: var(--ink-strong); border-color: #fff; }
.btn-light:hover { background: #fde047; border-color: #fde047; color: var(--ink-strong); }
.btn-outline-light { background: transparent; color: #fff; border-color: #fff; }
.btn-outline-light:hover { background: rgba(30, 27, 75, 0.6); border-color: #fff; }

.button-row { display: flex; flex-wrap: wrap; gap: 0.75rem; }

/* ---------- Forms ---------- */
.field { margin-bottom: 1.1rem; }
.field label,
.label {
  display: block;
  font-weight: 700;
  color: var(--ink-strong);
  margin-bottom: 0.3rem;
}
.required { font-weight: 600; color: var(--danger); }
.hint { display: block; color: var(--muted); font-size: 0.95rem; margin-bottom: 0.3rem; }

input[type="text"],
input[type="email"],
input[type="search"],
select {
  width: 100%;
  max-width: 32rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  font: inherit;
  color: var(--ink);
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: 0.5rem;
}
input::placeholder { color: var(--border); opacity: 1; }
input:hover, select:hover { border-color: var(--ink-strong); }
input[aria-invalid="true"],
select[aria-invalid="true"] { border-color: var(--danger); border-width: 3px; }

input[type="checkbox"],
input[type="radio"] {
  width: 1.5rem;
  height: 1.5rem;
  margin: 0.1rem 0 0;
  flex: none;
  accent-color: var(--primary);
}

fieldset {
  border: 2px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem 1rem 1rem;
  margin: 0 0 1.25rem;
  min-width: 0;
}
fieldset[aria-invalid="true"] { border-color: var(--danger); border-width: 3px; }
legend { font-weight: 700; color: var(--ink-strong); padding: 0 0.4rem; }

.error-message {
  display: flex;
  gap: 0.4rem;
  color: var(--danger);
  font-weight: 700;
  margin: 0.3rem 0 0;
}
.error-message[hidden] { display: none; }
.error-message::before { content: "⚠"; }

.error-summary {
  border: 3px solid var(--danger);
  background: #fee2e2;
  color: #7f1d1d;
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
  margin-bottom: 1.5rem;
}
.error-summary h2 { color: #7f1d1d; font-size: 1.2rem; }
.error-summary ul { margin: 0; padding-left: 1.25rem; }
.error-summary a { color: #7f1d1d; font-weight: 700; }

.success-box {
  border: 3px solid #15803d;
  background: #dcfce7;
  color: #14532d;
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
  margin-bottom: 1.5rem;
}
.success-box h2 { color: #14532d; font-size: 1.25rem; }
.success-box h2::before { content: "✓ "; }
.success-box a { color: #14532d; font-weight: 700; }
.success-box > :last-child { margin-bottom: 0; }

.form-grid { display: grid; gap: 0 1.5rem; }
@media (min-width: 40em) {
  .form-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* ---------- Home ---------- */
.hero {
  background: var(--header-gradient);
  color: #fff;
  border-radius: 1rem;
  padding: 2rem 1.5rem;
  margin-bottom: 2rem;
}
.hero h1 { color: #fff; font-size: 2.25rem; }
.hero p { font-size: 1.15rem; max-width: 40rem; }
.hero a:not(.btn) { color: #fde047; }
.hero-search { margin: 1.5rem 0; max-width: 36rem; }
.hero-search label { color: #fff; font-weight: 700; display: block; margin-bottom: 0.3rem; }
.hero-search .search-row { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.hero-search input { flex: 1 1 14rem; border-color: #fff; }

.feature-grid,
.stat-grid {
  list-style: none;
  margin: 0 0 2rem;
  padding: 0;
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
}
.feature-card {
  height: 100%;
  border-radius: var(--radius);
  padding: 1.25rem;
  border-top: 0.5rem solid;
  box-shadow: 0 1px 3px rgba(30, 27, 75, 0.15);
}
.feature-card p:last-child { margin-bottom: 0; }
.feature-card svg { width: 2.5rem; height: 2.5rem; margin-bottom: 0.5rem; }
.tint-indigo { background: #e0e7ff; border-color: #4338ca; }
.tint-pink { background: #fce7f3; border-color: #be123c; }
.tint-teal { background: #ccfbf1; border-color: #0f766e; }
.tint-amber { background: #fef3c7; border-color: #b45309; }

.stat {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
  border-left: 0.5rem solid var(--primary);
}
.stat:nth-child(2) { border-left-color: #be123c; }
.stat:nth-child(3) { border-left-color: #0f766e; }
.stat:nth-child(4) { border-left-color: #b45309; }
.stat-number { display: block; font-size: 2rem; font-weight: 800; color: var(--ink-strong); line-height: 1.2; }

.dept-list { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 0.5rem; }
.dept-list a {
  display: inline-block;
  padding: 0.45rem 0.9rem;
  min-height: 2.5rem;
  border-radius: 999px;
  color: #fff;
  font-weight: 700;
  text-decoration: underline;
}
.dept-list a:hover { color: #fff; text-decoration-thickness: 0.15em; filter: brightness(0.85); }

/* ---------- Catalog ---------- */
.filters {
  display: grid;
  gap: 0 1rem;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr));
  align-items: end;
}
.filters .field { margin-bottom: 1rem; }
.filters select { max-width: none; }
.search-field input { max-width: none; }
.search-row { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.search-row input { flex: 1 1 14rem; }

.results-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  margin-bottom: 1rem;
}
.results-count { font-weight: 700; font-size: 1.1rem; color: var(--ink-strong); margin: 0; }

.course-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1.25rem;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 19rem), 1fr));
}
.course-list > li { display: flex; }
.course-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  background: var(--surface);
  border-radius: var(--radius);
  border-top: 0.5rem solid var(--dept-color, var(--primary));
  box-shadow: 0 1px 4px rgba(30, 27, 75, 0.2);
  padding: 1rem 1.25rem 1.25rem;
}
.course-card h3 { margin-bottom: 0.4rem; }
.course-code { display: block; font-size: 0.95rem; color: var(--muted); font-weight: 700; }
.course-card .badges { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-bottom: 0.75rem; }
.course-card dl { margin: 0 0 1rem; display: grid; grid-template-columns: auto 1fr; gap: 0.15rem 0.75rem; }
.course-card dt { font-weight: 700; color: var(--ink-strong); }
.course-card dd { margin: 0; }
.course-card .card-action { margin-top: auto; }
.course-card .card-action p { margin: 0; font-weight: 700; color: var(--muted); }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.15rem 0.6rem;
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 700;
  line-height: 1.5;
}
.badge-dept { color: #fff; }
.badge-open { background: #dcfce7; color: #14532d; border: 1px solid #15803d; }
.badge-few { background: #fef3c7; color: #78350f; border: 1px solid #b45309; }
.badge-full { background: #fee2e2; color: #7f1d1d; border: 1px solid #b91c1c; }
.badge-registered { background: #e0e7ff; color: var(--ink-strong); border: 1px solid var(--primary); }

.empty-state {
  background: var(--surface);
  border: 2px dashed var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  text-align: center;
}

/* ---------- Registration ---------- */
.course-options { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.5rem; }
.course-option {
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  padding: 0.6rem 0.75rem;
  border-radius: 0.5rem;
  border-left: 0.35rem solid var(--dept-color, var(--primary));
  background: #faf5ff;
}
.course-option label { font-weight: 400; margin: 0; cursor: pointer; flex: 1; }
.course-option strong { color: var(--ink-strong); }
.course-option .option-meta { display: block; color: var(--muted); font-size: 0.95rem; }
.course-option.is-unavailable { background: #f3f4f6; }
.course-option.is-unavailable label { cursor: default; }

.credit-meter {
  font-weight: 700;
  color: var(--ink-strong);
  background: #e0e7ff;
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
  margin: 0 0 1rem;
}

/* ---------- Profile ---------- */
.profile-grid { display: grid; gap: 1.5rem; }
@media (min-width: 60em) {
  .profile-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); align-items: start; }
}
.profile-summary dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 0.35rem 1rem; }
.profile-summary dt { font-weight: 700; color: var(--ink-strong); }
.profile-summary dd { margin: 0; overflow-wrap: anywhere; }
.avatar {
  width: 4rem; height: 4rem;
  border-radius: 50%;
  display: grid; place-items: center;
  background: linear-gradient(135deg, #be123c, #7e22ce);
  color: #fff;
  font-weight: 800;
  font-size: 1.4rem;
  margin-bottom: 0.75rem;
}

.table-wrap {
  overflow-x: auto;
  border-radius: var(--radius);
  border: 2px solid var(--border);
  background: var(--surface);
  margin-bottom: 1rem;
}
table { border-collapse: collapse; width: 100%; min-width: 44rem; }
caption {
  text-align: left;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--ink-strong);
  padding: 0.75rem 1rem;
  background: #ede9fe;
}
th, td { padding: 0.6rem 0.9rem; text-align: left; vertical-align: top; border-bottom: 1px solid #d1d5db; }
thead th { background: var(--primary-dark); color: #fff; }
tbody th { color: var(--ink-strong); }
tbody tr:nth-child(even) { background: #f5f3ff; }
tfoot td, tfoot th { font-weight: 700; background: #ede9fe; color: var(--ink-strong); border-bottom: 0; }

/* ---------- Dialog ---------- */
dialog {
  width: min(32rem, calc(100% - 2rem));
  max-height: calc(100% - 2rem);
  overflow: auto;
  border: 0;
  border-top: 0.5rem solid var(--accent);
  border-radius: var(--radius);
  padding: 1.5rem;
  color: var(--ink);
  background: var(--surface);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.35);
}
dialog::backdrop { background: rgba(30, 27, 75, 0.7); }
dialog h2 { font-size: 1.4rem; }
dialog ul { padding-left: 1.25rem; }
dialog .button-row { justify-content: flex-end; margin-top: 1.25rem; }

/* ---------- Motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ---------- Forced colors (Windows High Contrast) ---------- */
@media (forced-colors: active) {
  .badge, .btn, .nav-list a[aria-current="page"] { border: 1px solid CanvasText; }
}
EOF

