  font-weight: 700;
  color: var(--ink-strong);
  margin-bottom: 0.3rem;
}
.required { font-weight: 600; color: var(--danger); }
.hint { display: block; color: var(--muted); font-size: 0.95rem; margin-bottom: 0.3rem; }

input[type="text"],
input[type="email"],
input[type="search"],
select {
  width: 100%;
  max-width: 32rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  font: inherit;
  color: var(--ink);
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: 0.5rem;
