    if (!name) errors.push([fields.name, "p-name-error", "Enter your full name."]);
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push([fields.email, "p-email-error", "Enter an email address in the format name@example.edu."]);
