p='js/data.js';s=open(p).read()
old=s[s.index('const Store = {'):s.index('  getProfile()')]
new='''/* In-memory copy, so the app still works for this page view when localStorage is unavailable. */
const memoryStore = {};

const Store = {
  read(key, fallback) {
    if (Object.prototype.hasOwnProperty.call(memoryStore, key)) return JSON.parse(memoryStore[key]);
    try {
      const raw = window.localStorage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch (e) {
      return fallback;
    }
  },
  write(key, value) {
    memoryStore[key] = JSON.stringify(value);
    try {
      window.localStorage.setItem(key, memoryStore[key]);
    } catch (e) {
      /* Storage can be unavailable (private mode or file restrictions). The memory copy is used instead. */
    }
  },
'''
s=s.replace(old,new);open(p,'w').write(s)
EOF
